// Typed access to the research data. The JSON files in src/data are generated by
// scripts/build_tables.py from research/*.json — edit the research files, not these.
import statesRaw from "../data/states.json";
import countiesRaw from "../data/ca-counties.json";
import caRaw from "../data/ca-statewide.json";

export interface Source {
  url: string;
  what?: string;
  type?: string;
}

export interface StateRow {
  state: string;
  abbr: string;
  slug: string;
  court_name: string | null;
  limit_individual: number | null;
  limit_business: number | null;
  limit_notes: string | null;
  recent_changes: string | null;
  filing_fee_min: number | null;
  filing_fee_max: number | null;
  filing_fee_notes: string | null;
  who_can_sue: string | null;
  lawyers_allowed: string | null;
  lawyers_notes: string | null;
  appeal: string | null;
  appeal_who: string | null;
  appeal_deadline_days: number | null;
  e_filing: string | null;
  e_filing_notes: string | null;
  fee_waiver_form: string | null;
  fee_waiver_threshold: string | null;
  service_methods: string | null;
  self_help_url: string | null;
  citation: string | null;
  sources: Source[];
  date_checked: string | null;
  unverified: string[];
  notes: string | null;
}

export interface Location {
  name: string;
  address: string;
  notes?: string;
}

export interface CountyRow {
  county: string;
  slug: string;
  court_name: string;
  small_claims_page_url: string | null;
  small_claims_locations: Location[];
  self_help_center: { name?: string; address?: string; phone?: string; url?: string; notes?: string } | null;
  small_claims_advisor: {
    provider?: string;
    phone?: string;
    url?: string;
    email?: string;
    format?: string;
    free?: boolean;
    notes?: string;
  } | null;
  e_filing: string | null;
  e_filing_notes: string | null;
  remote_hearings: string | null;
  local_notes: string | null;
  sources: Source[];
  date_checked: string | null;
  unverified: string[];
  notes: string | null;
}

export const states = (statesRaw as StateRow[]).slice().sort((a, b) => a.state.localeCompare(b.state));
export const counties = (countiesRaw as CountyRow[]).slice().sort((a, b) => a.county.localeCompare(b.county));
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const caStatewide = caRaw as any;

export function stateBySlug(slug: string) {
  return states.find((s) => s.slug === slug);
}

export function isUnverified(row: { unverified: string[] }, ...fields: string[]) {
  return fields.some((f) => row.unverified?.includes(f));
}

export function money(n: number | null | undefined) {
  if (n == null) return "—";
  const cents = Number.isInteger(n) ? 0 : 2;
  return n.toLocaleString("en-US", { style: "currency", currency: "USD", minimumFractionDigits: cents, maximumFractionDigits: cents });
}

export function feeRange(r: StateRow) {
  if (r.filing_fee_min == null && r.filing_fee_max == null) return "—";
  if (r.filing_fee_min === r.filing_fee_max || r.filing_fee_max == null) return money(r.filing_fee_min);
  if (r.filing_fee_min == null) return `up to ${money(r.filing_fee_max)}`;
  return `${money(r.filing_fee_min)}–${money(r.filing_fee_max)}`;
}

